using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using pet_project.Data; using pet_project.Models; namespace pet_project.Controllers;
public class AdoptersController:Controller { readonly AppDbContext c; public AdoptersController(AppDbContext c)=>this.c=c; public async Task<IActionResult>Index()=>View(await c.Adopters.ToListAsync()); public async Task<IActionResult>Details(int? id){if(id==null)return NotFound();var x=await c.Adopters.Include(x=>x.Applications).ThenInclude(a=>a.Pet).FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():View(x);} public IActionResult Create()=>View(); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Create([Bind("Id,FullName,Email,Phone")]Adopter x){if(!ModelState.IsValid)return View(x);c.Add(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult>Edit(int? id){if(id==null)return NotFound();var x=await c.Adopters.FindAsync(id);return x==null?NotFound():View(x);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Edit(int id,[Bind("Id,FullName,Email,Phone")]Adopter x){if(id!=x.Id)return NotFound();if(!ModelState.IsValid)return View(x);c.Update(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult>Delete(int? id){if(id==null)return NotFound();var x=await c.Adopters.FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():View(x);} [HttpPost,ActionName("Delete"),ValidateAntiForgeryToken] public async Task<IActionResult>DeleteConfirmed(int id){var x=await c.Adopters.FindAsync(id);if(x!=null)c.Adopters.Remove(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} }
